1	/**
2	 * R2-backed WorkspaceOperationLogStore for Cloudflare Workers.
3	 *
4	 * Design notes mirror those for r2-run-log-store.ts:
5	 * - R2 objects are immutable; append semantics are emulated by read-modify-PUT.
6	 * - Key sharding is used when a shard exceeds CHUNK_BYTE_LIMIT bytes.
7	 *   Shard keys: `workspace-op-logs/<companyId>/<operationId>/chunk-<n>.ndjson`.
8	 * - All APIs are Web-platform only. No `node:fs`, `node:stream`, or
9	 *   `node:crypto`.
10	 * - The `logRef` in WorkspaceOperationLogHandle is the base key prefix
11	 *   `workspace-op-logs/<companyId>/<operationId>`.
12	 */
13	
14	import type {
15	  WorkspaceOperationLogHandle,
16	  WorkspaceOperationLogReadOptions,
17	  WorkspaceOperationLogReadResult,
18	  WorkspaceOperationLogFinalizeSummary,
19	  WorkspaceOperationLogStore,
20	} from "../../../../server/src/services/workspace-operation-log-store.js";
21	
22	export type {
23	  WorkspaceOperationLogHandle,
24	  WorkspaceOperationLogReadOptions,
25	  WorkspaceOperationLogReadResult,
26	  WorkspaceOperationLogFinalizeSummary,
27	  WorkspaceOperationLogStore,
28	};
29	
30	/** Maximum bytes buffered in a single R2 object before spilling to a new shard. */
31	const CHUNK_BYTE_LIMIT = 128 * 1024; // 128 KiB
32	
33	/** Default read window when no limitBytes is specified. */
34	const DEFAULT_READ_LIMIT = 256_000;
35	
36	const encoder = new TextEncoder();
37	const decoder = new TextDecoder();
38	
39	function safeSegment(value: string): string {
40	  return value.replace(/[^a-zA-Z0-9._-]/g, "_");
41	}
42	
43	/** Build the key for shard index n under a given base prefix. */
44	function shardKey(baseKey: string, n: number): string {
45	  return `${baseKey}/chunk-${n}.ndjson`;
46	}
47	
48	/** Parse the shard index from a shard key, or return -1 if not a shard key. */
49	function parseShardIndex(key: string): number {
50	  const match = /\/chunk-(\d+)\.ndjson$/.exec(key);
51	  return match ? parseInt(match[1]!, 10) : -1;
52	}
53	
54	/**
55	 * Discover the highest-indexed shard that exists for the given base key.
56	 * Returns 0 if only chunk-0 exists, or -1 if no shards exist at all.
57	 */
58	async function highestShardIndex(bucket: R2Bucket, baseKey: string, prefix: string): Promise<number> {
59	  const listed = await bucket.list({ prefix: `${prefix}${baseKey}/` });
60	  let max = -1;
61	  for (const obj of listed.objects) {
62	    const relKey = obj.key.slice(prefix.length);
63	    const idx = parseShardIndex(relKey);
64	    if (idx > max) max = idx;
65	  }
66	  return max;
67	}
68	
69	/** Read the full text content of an R2 object, or return "" if it does not exist. */
70	async function readObjectText(bucket: R2Bucket, fullKey: string): Promise<string> {
71	  const obj = await bucket.get(fullKey);
72	  if (!obj) return "";
73	  const buf = await obj.arrayBuffer();
74	  return decoder.decode(buf);
75	}
76	
77	/** Compute a SHA-256 hex digest of a UTF-8 string using the Web Crypto API. */
78	async function sha256Hex(text: string): Promise<string> {
79	  const buf = encoder.encode(text);
80	  const hashBuf = await crypto.subtle.digest("SHA-256", buf);
81	  return Array.from(new Uint8Array(hashBuf))
82	    .map((b) => b.toString(16).padStart(2, "0"))
83	    .join("");
84	}
85	
86	export interface R2WorkspaceOpLogStoreConfig {
87	  /**
88	   * Optional key prefix applied to every object key before passing to R2.
89	   * Example: `"prod/"` makes all keys `"prod/workspace-op-logs/..."`.
90	   */
91	  prefix?: string;
92	}
93	
94	/**
95	 * Creates a `WorkspaceOperationLogStore` backed by a Cloudflare R2 bucket.
96	 *
97	 * The store type discriminant stored in `WorkspaceOperationLogHandle.store` is
98	 * `"r2"` so callers that branch on `handle.store` can distinguish this
99	 * implementation from the Node local-file one.
100	 */
101	export function createR2WorkspaceOpLogStore(
102	  bucket: R2Bucket,
103	  config?: R2WorkspaceOpLogStoreConfig,
104	): WorkspaceOperationLogStore {
105	  const prefix = config?.prefix ?? "";
106	
107	  function fullKey(objectKey: string): string {
108	    return prefix ? `${prefix}${objectKey}` : objectKey;
109	  }
110	
111	  return {
112	    async begin(input) {
113	      const companyId = safeSegment(input.companyId);
114	      const operationId = safeSegment(input.operationId);
115	      const baseKey = `workspace-op-logs/${companyId}/${operationId}`;
116	
117	      // Write an empty chunk-0 to mark the log as started.
118	      await bucket.put(fullKey(shardKey(baseKey, 0)), new Uint8Array(0), {
119	        httpMetadata: { contentType: "application/x-ndjson" },
120	      });
121	
122	      return { store: "r2" as const, logRef: baseKey };
123	    },
124	
125	    async append(handle, event) {
126	      if (handle.store !== "r2") return;
127	      const baseKey = handle.logRef;
128	
129	      const shardIdx = await highestShardIndex(bucket, baseKey, prefix);
130	      const activeShardIdx = shardIdx < 0 ? 0 : shardIdx;
131	      const activeKey = fullKey(shardKey(baseKey, activeShardIdx));
132	
133	      const existing = await readObjectText(bucket, activeKey);
134	
135	      const line = JSON.stringify({ ts: event.ts, stream: event.stream, chunk: event.chunk });
136	      const newLine = `${line}\n`;
137	      const newLineBytes = encoder.encode(newLine);
138	
139	      let writeKey = activeKey;
140	      let newContent: string;
141	
142	      if (encoder.encode(existing).byteLength + newLineBytes.byteLength > CHUNK_BYTE_LIMIT) {
143	        writeKey = fullKey(shardKey(baseKey, activeShardIdx + 1));
144	        newContent = newLine;
145	      } else {
146	        newContent = existing + newLine;
147	      }
148	
149	      const encoded = encoder.encode(newContent);
150	      await bucket.put(writeKey, encoded, {
151	        httpMetadata: { contentType: "application/x-ndjson" },
152	      });
153	    },
154	
155	    async finalize(handle) {
156	      if (handle.store !== "r2") {
157	        return { bytes: 0, compressed: false };
158	      }
159	      const baseKey = handle.logRef;
160	
161	      const shardIdx = await highestShardIndex(bucket, baseKey, prefix);
162	      if (shardIdx < 0) {
163	        return { bytes: 0, compressed: false };
164	      }
165	
166	      let totalBytes = 0;
167	      let fullContent = "";
168	
169	      for (let i = 0; i <= shardIdx; i++) {
170	        const text = await readObjectText(bucket, fullKey(shardKey(baseKey, i)));
171	        fullContent += text;
172	        totalBytes += encoder.encode(text).byteLength;
173	      }
174	
175	      const sha256 = await sha256Hex(fullContent);
176	
177	      return {
178	        bytes: totalBytes,
179	        sha256,
180	        compressed: false,
181	      };
182	    },
183	
184	    async read(handle, opts) {
185	      if (handle.store !== "r2") {
186	        throw new Error("Workspace operation log not found");
187	      }
188	      const baseKey = handle.logRef;
189	      const offset = opts?.offset ?? 0;
190	      const limitBytes = opts?.limitBytes ?? DEFAULT_READ_LIMIT;
191	
192	      const shardIdx = await highestShardIndex(bucket, baseKey, prefix);
193	      if (shardIdx < 0) {
194	        return { content: "" };
195	      }
196	
197	      let fullContent = "";
198	      for (let i = 0; i <= shardIdx; i++) {
199	        fullContent += await readObjectText(bucket, fullKey(shardKey(baseKey, i)));
200	      }
201	
202	      const allBytes = encoder.encode(fullContent);
203	      const totalSize = allBytes.byteLength;
204	
205	      const start = Math.max(0, Math.min(offset, totalSize));
206	      const end = Math.min(start + limitBytes, totalSize);
207	
208	      if (start >= end) {
209	        return { content: "", nextOffset: start < totalSize ? start : undefined };
210	      }
211	
212	      const slice = allBytes.slice(start, end);
213	      const content = decoder.decode(slice);
214	      const nextOffset = end < totalSize ? end : undefined;
215	
216	      return { content, nextOffset };
217	    },
218	  };
219	}
